      "content": {
        "version": "KqlItem/1.0",
        "query": "let Reg = YumaAIRegister();\nunion\n    (Reg | summarize Value = count() | extend Label = \"Active agents and AI apps\", Ord = 1),\n    (Reg | where GapCount > 0 | summarize Value = count() | extend Label = \"Missing ISM-2135 fields\", Ord = 2),\n    (Reg | where ReviewStatus in (\"Overdue\", \"Never reviewed\") | summarize Value = count() | extend Label = \"Review overdue (ISM-2138)\", Ord = 3),\n    (Reg | where Flag_HighRiskPermissions | summarize Value = count() | extend Label = \"High-risk permissions (ISM-2156)\", Ord = 4),\n    (Reg | where Flag_HasMcp | summarize Value = count() | extend Label = \"Agents using MCP servers\", Ord = 5)\n| order by Ord asc\n| project Label, Value",
        "size": 0,
        "title": "Register at a glance",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "visualization": "tiles",
        "tileSettings": {
          "titleContent": {
